     1	package app
     2	
     3	import (
     4		"fmt"
     5		"strings"
     6	
     7		tea "github.com/charmbracelet/bubbletea"
     8	
     9		"github.com/anthnel/devdesk/internal/command"
    10		"github.com/anthnel/devdesk/internal/contextcmd"
    11		"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
    12		"github.com/anthnel/devdesk/internal/ui/components"
    13	)
    14	
    15	// argStage reports whether the list shows argument rows: the :ctx command at
    16	// its argument stage. Other commands keep the single command row.
    17	func (a *App) argStage() bool {
    18		return a.suggestions.Stage == command.StageArgument &&
    19			command.ParseCommand(a.commandInput.Value()).Type == command.CommandContext
    20	}
    21	
    22	// listRowCount is how many rows the list holds at the current stage.
    23	func (a *App) listRowCount() int {
    24		if a.argStage() {
    25			return len(a.suggestions.Args)
    26		}
    27		return len(a.suggestions.Entries)
    28	}
    29	
    30	// ctxArgText is the text typed after the command word, trimmed on the left.
    31	func (a *App) ctxArgText() string {
    32		_, rest, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
    33		return strings.TrimLeft(rest, " ")
    34	}
    35	
    36	// defaultArgCursor picks the row highlighted when the argument list is drawn:
    37	// the exact match; else the only match when contextcmd accepts it as a valid
    38	// name; else none.
    39	func (a *App) defaultArgCursor() int {
    40		args := a.suggestions.Args
    41		prefix := a.ctxArgText()
    42		if prefix == "" || !a.suggestions.ArgsReady {
    43			return -1
    44		}
    45		for i, s := range args {
    46			if s.Value == prefix {
    47				return i
    48			}
    49		}
    50		if len(args) != 1 {
    51			return -1
    52		}
    53		if !validContextText(prefix) {
    54			return -1
    55		}
    56		return 0
    57	}
    58	
    59	// validContextText reports whether s is made of lowercase letters, digits and
    60	// hyphens, the characters a context name may hold.
    61	func validContextText(s string) bool {
    62		for _, r := range s {
    63			if (r < 'a' || r > 'z') && (r < '0' || r > '9') && r != '-' {
    64				return false
    65			}
    66		}
    67		return s != ""
    68	}
    69	
    70	// argHeading is the rule's label at the argument stage: contexts shown out of
    71	// all contexts, the reserved words not counted.
    72	func (a *App) argHeading() string {
    73		shown := 0
    74		for _, s := range a.suggestions.Args {
    75			if s.Value != contextcmd.WordPrevious && s.Value != contextcmd.WordNew {
    76				shown++
    77			}
    78		}
    79		return fmt.Sprintf("Contexts · %d of %d", shown, len(a.snapshot().Names))
    80	}
    81	
    82	// argRows renders the argument suggestions as list rows.
    83	func (a *App) argRows() []cmdsuggest.Row {
    84		rows := make([]cmdsuggest.Row, len(a.suggestions.Args))
    85		for i := range a.suggestions.Args {
    86			s := a.suggestions.Args[i]
    87			rows[i] = cmdsuggest.Row{Arg: &s, Current: s.Current}
    88		}
    89		return rows
    90	}
    91	
    92	// argEmpty is the message of an argument list with no rows.
    93	func (a *App) argEmpty() string {
    94		prefix := a.ctxArgText()
    95		if strings.HasPrefix(strings.ToLower(prefix), contextcmd.WordNew+" ") {
    96			return ""
    97		}
    98		return fmt.Sprintf("No context starts with %q", prefix)
    99	}
   100	
   101	// highlightedArg returns the value of the highlighted argument row, or "".
   102	func (a *App) highlightedArg() string {
   103		if !a.argStage() || a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Args) {
   104			return ""
   105		}
   106		return a.suggestions.Args[a.sugCursor].Value
   107	}
   108	
   109	// completeArg is tab at the argument stage: it highlights the first row when
   110	// none is, otherwise writes the highlighted value into the line.
   111	func (a *App) completeArg() {
   112		if len(a.suggestions.Args) == 0 {
   113			return
   114		}
   115		if a.sugCursor < 0 {
   116			a.sugCursor = a.sugOffset
   117			return
   118		}
   119		word, _, _ := strings.Cut(strings.TrimLeft(a.commandInput.Value(), ": "), " ")
   120		text := word + " " + a.highlightedArg()
   121		if a.highlightedArg() == contextcmd.WordNew {
   122			text += " "
   123		}
   124		a.commandInput.SetValue(text)
   125		a.commandInput.CursorEnd()
   126		a.refreshSuggestions()
   127	}
   128	
   129	// runContext is enter on a :ctx command line.
   130	func (a *App) runContext(args []string) (tea.Model, tea.Cmd) {
   131		highlighted := a.highlightedArg()
   132		if len(args) == 0 && highlighted != "" {
   133			args = []string{highlighted}
   134		}
   135		action := contextcmd.Resolve(args, highlighted, a.snapshot())
   136		if action.Kind == contextcmd.KeepOpen {
   137			a.sugNotice = action.Text
   138			return a, nil
   139		}
   140		a.closeCommandLineQuiet()
   141		switch action.Kind {
   142		case contextcmd.Switch:
   143			return a, a.switchContext(action.Name)
   144		case contextcmd.Create:
   145			return a, a.createContext(action.Name)
   146		case contextcmd.Refuse:
   147			return a, components.PostFooter(footerLevel(action.Level), action.Text)
   148		}
   149		return a, a.listContexts()
   150	}
   151	
   152	// closeCommandLineQuiet leaves command mode; the caller returns the Cmd that
   153	// follows (the re-layout happens on the next resize).
   154	func (a *App) closeCommandLineQuiet() {
   155		a.commandMode = false
   156		a.commandInput.Blur()
   157		a.resetSuggestions()
   158	}
   159	
   160	// footerLevel maps a contextcmd level to a footer level.
   161	func footerLevel(l contextcmd.Level) components.Level {
   162		switch l {
   163		case contextcmd.Warn:
   164			return components.LevelWarning
   165		case contextcmd.Error:
   166			return components.LevelError
   167		}
   168		return components.LevelInfo
   169	}
   170	
   171	// createContext is the extension point for ":ctx new <name>".
   172	// TODO(DEVDESK-116, step 7): create the context and switch to it. Until then
   173	// it creates nothing.
   174	func (a *App) createContext(_ string) tea.Cmd { return nil }
     1	package app
     2	
     3	import (
     4		"log"
     5		"sort"
     6		"strings"
     7	
     8		tea "github.com/charmbracelet/bubbletea"
     9	
    10		"github.com/anthnel/devdesk/internal/command"
    11		"github.com/anthnel/devdesk/internal/config"
    12		"github.com/anthnel/devdesk/internal/contextcmd"
    13		"github.com/anthnel/devdesk/internal/ui/components"
    14	)
    15	
    16	const (
    17		noteNewContext      = "Create a context"
    18		notePreviousContext = "Previous context"
    19	)
    20	
    21	// contextNamesLoadedMsg carries the context names read off disk when the
    22	// command line opened.
    23	type contextNamesLoadedMsg struct {
    24		Names []string
    25		Err   error
    26	}
    27	
    28	// contextArgs is the in-memory snapshot behind the context argument provider.
    29	// Only Update() writes it (Rule 110); SuggestArgs never touches the disk.
    30	type contextArgs struct {
    31		names   []string
    32		ready   bool
    33		current string
    34	}
    35	
    36	// SuggestArgs implements command.ArgProvider from the snapshot only.
    37	func (c *contextArgs) SuggestArgs(prefix string) ([]command.ArgSuggestion, bool) {
    38		if !c.ready {
    39			return nil, false
    40		}
    41		// "new" alone is a plain prefix (it may start a context name); "new " or
    42		// "new x" is the creation form, where there is nothing left to complete.
    43		if p := strings.ToLower(prefix); strings.HasPrefix(p, contextcmd.WordNew+" ") {
    44			return nil, true
    45		}
    46		var out []command.ArgSuggestion
    47		for _, n := range contextcmd.Match(prefix, c.names) {
    48			out = append(out, command.ArgSuggestion{Value: n, Current: n == c.current})
    49		}
    50		for _, s := range []command.ArgSuggestion{
    51			{Value: contextcmd.WordPrevious, Note: notePreviousContext},
    52			{Value: contextcmd.WordNew, Note: noteNewContext},
    53		} {
    54			if strings.HasPrefix(s.Value, strings.ToLower(prefix)) {
    55				out = append(out, s)
    56			}
    57		}
    58		return out, true
    59	}
    60	
    61	// loadContextNamesCmd lists the contexts off the Update goroutine.
    62	func loadContextNamesCmd() tea.Cmd {
    63		return func() tea.Msg {
    64			names, err := config.ListContexts()
    65			sort.Strings(names)
    66			return contextNamesLoadedMsg{Names: names, Err: err}
    67		}
    68	}
    69	
    70	// handleContextNamesLoaded stores the names read when the command line opened.
    71	func (a *App) handleContextNamesLoaded(msg contextNamesLoadedMsg) (tea.Model, tea.Cmd) {
    72		if msg.Err != nil {
    73			log.Printf("ERROR [app/context] list contexts: %v", msg.Err)
    74			a.ctxArgs.ready = false
    75			if a.commandMode {
    76				a.refreshSuggestionsKeepCursor()
    77			}
    78			return a, components.PostFooter(components.LevelError, "Failed to list contexts — check logs")
    79		}
    80		a.ctxArgs.names, a.ctxArgs.ready = msg.Names, true
    81		a.ctxArgs.current = a.currentContext
    82		if a.commandMode {
    83			a.refreshSuggestionsKeepCursor()
    84		}
    85		return a, nil
    86	}
    87	
    88	// snapshot returns the contexts known to the router.
    89	func (a *App) snapshot() contextcmd.Snapshot {
    90		if a.ctxArgs == nil {
    91			return contextcmd.Snapshot{Current: a.currentContext, Previous: a.previousContext}
    92		}
    93		return contextcmd.Snapshot{
    94			Names:    a.ctxArgs.names,
    95			Current:  a.currentContext,
    96			Previous: a.previousContext,
    97			Ready:    a.ctxArgs.ready,
    98		}
    99	}
