     8	)
     9	
    10	// Snapshot is the state of the world Resolve decides against.
    11	type Snapshot struct {
    12		Names             []string
    13		Current, Previous string
    14		Ready             bool
    15	}
    16	
    17	// Kind is what the caller must do with an Action.
    18	type Kind int
    19	
    20	const (
    21		// List opens the context list overlay.
    22		List Kind = iota
    23		// Switch loads the context named Name.
    24		Switch
    25		// Create creates the context named Name and switches to it.
    26		Create
    27		// Refuse does nothing but report Text.
    28		Refuse
    29		// KeepOpen leaves the command line open and reports Text.
    30		KeepOpen
    31	)
    32	
    33	// Level is the footer severity of an Action's Text.
    34	type Level int
    35	
    36	const (
    37		// Info is a neutral fact.
    38		Info Level = iota
    39		// Warn means the request cannot be honored as typed.
    40		Warn
    41		// Error means the request is invalid or failed.
    42		Error
    43	)
    44	
    45	// Action is the outcome of Resolve.
    46	type Action struct {
    47		Kind  Kind
    48		Name  string
    49		Level Level
    50		Text  string
    51	}
    52	
    53	const (
    54		// WordNew and WordPrevious are the reserved words of the context command.
    55		WordNew      = "new"
    56		wordList     = "list"
    57		WordPrevious = "-"
    58	
    59		textUsageNew = "Usage: :ctx new <name>"
    60		textUsage    = "Usage: :ctx <name>"
    61		textNoPrev   = "No previous context in this session"
    62		textNotReady = "Contexts are still loading — try again"
    63	)
    64	
    65	func textAlready(name string) string { return fmt.Sprintf("Already on context %q", name) }
    66	
    67	func textInvalid(name string) string {
    68		return fmt.Sprintf("Invalid context name %q — use lowercase letters, digits and hyphens", name)
    69	}
    70	
    71	func textReserved(name string) string {
    72		return fmt.Sprintf("%q is reserved — choose another name", name)
    73	}
    74	
    75	func textExists(name string) string {
    76		return fmt.Sprintf("Context %q already exists — use :ctx %s to switch", name, name)
    77	}
    78	
    79	// maxListedMatches caps how many ambiguous matches the footer names.
    80	const maxListedMatches = 10
    81	
    82	func textAmbiguous(prefix string, matches []string) string {
    83		list := strings.Join(matches, ", ")
    84		if len(matches) > maxListedMatches {
    85			list = strings.Join(matches[:maxListedMatches], ", ") +
    86				fmt.Sprintf(", and %d more", len(matches)-maxListedMatches)
    87		}
    88		return fmt.Sprintf("%q matches %s — type more letters or press tab", prefix, list)
    89	}
    90	
    91	func textPreviousGone(name string) string {
    92		return fmt.Sprintf("Previous context %q no longer exists", name)
    93	}
    94	
    95	func textNotFound(name string, names []string) string {
    96		if near, ok := DidYouMean(name, names); ok {
    97			return fmt.Sprintf("Context %q not found — did you mean %q? Use :ctx new %s to create it", name, near, name)
    98		}
    99		return fmt.Sprintf("Context %q not found — use :ctx new %s to create it", name, name)
   100	}
