   102	func refuse(level Level, text string) Action { return Action{Kind: Refuse, Level: level, Text: text} }
   103	
   104	func keepOpen(level Level, text string) Action {
   105		return Action{Kind: KeepOpen, Level: level, Text: text}
   106	}
   107	
   108	// validName reports whether name is made of lowercase letters, digits and
   109	// hyphens only, mirroring config.ValidateContextName without importing it.
   110	func validName(name string) bool {
   111		if name == "" {
   112			return false
   113		}
   114		for _, r := range name {
   115			if (r < 'a' || r > 'z') && (r < '0' || r > '9') && r != '-' {
   116				return false
   117			}
   118		}
   119		return true
   120	}
   121	
   122	// cleanNames drops empty names and duplicates, keeping the first occurrence.
   123	func cleanNames(names []string) []string {
   124		out := make([]string, 0, len(names))
   125		for _, n := range names {
   126			if n != "" && !contains(out, n) {
   127				out = append(out, n)
   128			}
   129		}
   130		return out
   131	}
   132	
   133	func contains(names []string, name string) bool {
   134		for _, n := range names {
   135			if n == name {
   136				return true
   137			}
   138		}
   139		return false
   140	}
   141	
   142	// switchTo switches to name, or reports that it is already the current one.
   143	func switchTo(name string, s Snapshot) Action {
   144		if name == s.Current {
   145			return refuse(Info, textAlready(name))
   146		}
   147		return Action{Kind: Switch, Name: name}
   148	}
   149	
   150	// Resolve interprets the words after :ctx. highlighted is the suggestion the
   151	// user chose with tab, or "" when none was chosen.
   152	func Resolve(args []string, highlighted string, s Snapshot) Action {
   153		s.Names = cleanNames(s.Names)
   154		if len(args) == 0 || (len(args) == 1 && args[0] == wordList) {
   155			return Action{Kind: List}
   156		}
   157		if !s.Ready {
   158			return keepOpen(Warn, textNotReady)
   159		}
   160		if args[0] == WordNew {
   161			return resolveNew(args[1:], s)
   162		}
   163		if len(args) > 1 {
   164			return keepOpen(Warn, textUsage)
   165		}
   166		return resolveName(args[0], highlighted, s)
   167	}
   168	
   169	// resolveNew handles ":ctx new <name>".
   170	func resolveNew(rest []string, s Snapshot) Action {
   171		if len(rest) != 1 {
   172			return keepOpen(Warn, textUsageNew)
   173		}
   174		name := rest[0]
   175		switch {
   176		case name == WordNew || name == wordList || name == WordPrevious:
   177			return refuse(Error, textReserved(name))
   178		case !validName(name):
   179			return refuse(Error, textInvalid(name))
   180		case contains(s.Names, name):
   181			return refuse(Warn, textExists(name))
   182		}
   183		return Action{Kind: Create, Name: name}
   184	}
   185	
   186	// resolveName handles ":ctx <arg>": previous, exact, prefix, or unknown.
   187	func resolveName(arg, highlighted string, s Snapshot) Action {
   188		if arg == WordPrevious {
   189			if s.Previous == "" {
   190				return refuse(Warn, textNoPrev)
   191			}
   192			if !contains(s.Names, s.Previous) {
   193				return refuse(Error, textPreviousGone(s.Previous))
   194			}
   195			return switchTo(s.Previous, s)
   196		}
   197		if !validName(arg) {
   198			return refuse(Error, textInvalid(arg))
   199		}
   200		if contains(s.Names, arg) {
   201			return switchTo(arg, s)
   202		}
   203		matches := Match(arg, s.Names)
   204		switch {
   205		case len(matches) == 0:
   206			return refuse(Error, textNotFound(arg, s.Names))
   207		case len(matches) == 1:
   208			return switchTo(matches[0], s)
   209		case contains(matches, highlighted):
   210			return switchTo(highlighted, s)
   211		}
   212		return keepOpen(Warn, textAmbiguous(arg, matches))
   213	}
   214	
   215	// Match returns the names starting with prefix (case-insensitive), an exact
   216	// match first, the others in their original order.
   217	func Match(prefix string, names []string) []string {
   218		p := strings.ToLower(prefix)
   219		out := []string{}
   220		for _, n := range names {
   221			if strings.ToLower(n) == p {
   222				out = append(out, n)
   223			}
   224		}
   225		for _, n := range names {
   226			l := strings.ToLower(n)
   227			if l != p && strings.HasPrefix(l, p) {
   228				out = append(out, n)
   229			}
   230		}
   231		return out
   232	}
   233	
   234	// DidYouMean returns the closest name: edit distance <= min(2, half the
   235	// shorter length), or a common start of at least 3 characters. Ties go to the
   236	// first name; empty names are never offered.
   237	func DidYouMean(name string, names []string) (string, bool) {
   238		best, bestDist := "", 0
   239		for _, n := range names {
   240			if n == "" {
   241				continue
   242			}
   243			d := editDistance(name, n)
   244			if d > maxDistance(name, n) && commonPrefixLen(name, n) < 3 {
   245				continue
   246			}
   247			if best == "" || d < bestDist {
   248				best, bestDist = n, d
   249			}
   250		}
   251		return best, best != ""
   252	}
   253	
   254	// maxDistance is the largest edit distance still considered a typo.
   255	func maxDistance(a, b string) int {
   256		return min(2, min(len([]rune(a)), len([]rune(b)))/2)
   257	}
   258	
   259	func commonPrefixLen(a, b string) int {
   260		ra, rb := []rune(a), []rune(b)
   261		n := 0
   262		for n < len(ra) && n < len(rb) && ra[n] == rb[n] {
   263			n++
   264		}
   265		return n
   266	}
   267	
   268	// editDistance is the Levenshtein distance between a and b.
   269	func editDistance(a, b string) int {
   270		ra, rb := []rune(a), []rune(b)
   271		prev := make([]int, len(rb)+1)
   272		for j := range prev {
   273			prev[j] = j
   274		}
   275		for i := 1; i <= len(ra); i++ {
   276			cur := make([]int, len(rb)+1)
   277			cur[0] = i
   278			for j := 1; j <= len(rb); j++ {
   279				cost := 1
   280				if ra[i-1] == rb[j-1] {
   281					cost = 0
   282				}
   283				cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
   284			}
   285			prev = cur
   286		}
   287		return prev[len(rb)]
   288	}
