1	package app
2	
3	import (
4		"strings"
5		"testing"
6	
7		"github.com/anthnel/devdesk/internal/command"
8		"github.com/anthnel/devdesk/internal/config"
9		"github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/testutil"
11	)
12	
13	// DEVDESK-88 step 6 (DEVDESK-115): the argument stage of the command line for
14	// :ctx — docs/ux/context-switch.md. Executing a switch or a creation is step 7;
15	// here a switch is observed through switchingTo and the overlay, and the Cmd
16	// is never run.
17	
18	// argRouter builds a router over an isolated HOME holding default, web, work;
19	// "default" is current. No snapshot is loaded yet.
20	func argRouter(t *testing.T, names ...string) *App {
21		t.Helper()
22		isolateHome(t)
23		if len(names) == 0 {
24			names = []string{"default", "web", "work"}
25		}
26		for _, n := range names {
27			if err := config.SaveContext(testConfig(), n); err != nil {
28				t.Fatalf("SaveContext(%q): %v", n, err)
29			}
30		}
31		a := newWithSize(testConfig(), 120, 40)
32		a.currentContext = names[0]
33		// A plain view keeps the viewport height predictable (the dashboard adds tabs).
34		a.views[command.ViewDashboard] = &fakeView{}
35		a.resize(120, 40)
36		return a
37	}
38	
39	// ctxOpen opens the command line, applies the context load, and types text.
40	func ctxOpen(t *testing.T, a *App, text string) {
41		t.Helper()
42		loadContexts(t, a)
43		typeCommand(t, a, text)
44	}
45	
46	func hasRowWith(rows []string, sub string) bool {
47		for _, r := range rows {
48			if strings.Contains(r, sub) {
49				return true
50			}
51		}
52		return false
53	}
54	
55	// footerOf presses key and returns the footer post it produced, if any.
56	func footerOf(t *testing.T, a *App, key string) (components.PostFooterMsg, bool) {
57		t.Helper()
58		testutil.FastTimers(t, &components.FooterMsgDuration)
59		return testutil.MsgOf[components.PostFooterMsg](press(t, a, key))
60	}
61	
62	// ── Display ──────────────────────────────────────────────────────────────────
63	
64	func TestCtxArgumentListShowsContextsThenReservedWords(t *testing.T) {
65		a := argRouter(t)
66		ctxOpen(t, a, "ctx ")
67	
68		rows := listRows(t, a)
69		if len(rows) != 5 {
70			t.Fatalf("%d rows, want 5 (3 contexts, -, new): %q", len(rows), rows)
71		}
72		for i, want := range []string{"default (current)", "web", "work", "-", "new"} {
73			if !strings.Contains(rows[i], want) {
74				t.Errorf("row %d = %q, want it to contain %q", i, rows[i], want)
75			}
76		}
77		if got := filet(t, a); !strings.Contains(got, "Contexts · 3 of 3") {
78			t.Errorf("rule %q lacks the heading %q", got, "Contexts · 3 of 3")
79		}
80	}
81	
82	func TestCtxArgumentFilterNarrowsRowsAndHeading(t *testing.T) {
83		a := argRouter(t)
84		ctxOpen(t, a, "ctx w")
85	
86		rows := listRows(t, a)
87		if len(rows) != 2 || !strings.Contains(rows[0], "web") || !strings.Contains(rows[1], "work") {
88			t.Errorf("rows %q, want web and work", rows)
89		}
90		if got := filet(t, a); !strings.Contains(got, "Contexts · 2 of 3") {
91			t.Errorf("rule %q lacks %q", got, "Contexts · 2 of 3")
92		}
93	}
94	
95	func TestCtxArgumentListScrollsInAWindowOfEight(t *testing.T) {
96		a := argRouter(t, "a01", "a02", "a03", "a04", "a05", "a06", "a07", "a08", "a09", "a10")
97		ctxOpen(t, a, "ctx ")
98	
99		if rows := listRows(t, a); len(rows) != maxListRows {
100			t.Errorf("%d rows, want %d", len(rows), maxListRows)
101		}
102		if got := filet(t, a); !strings.Contains(got, "▼ 4 more") {
103			t.Errorf("rule %q lacks %q (12 rows, 8 shown)", got, "▼ 4 more")
104		}
105		press(t, a, "tab") // highlights the first row, offset stays
106		for i := 0; i < 10; i++ {
107			press(t, a, "down")
108		}
109		if got := filet(t, a); !strings.Contains(got, "▲") {
110			t.Errorf("rule %q shows no scrolled-out rows after moving down", got)
111		}
112	}
113	
114	func TestCtxArgumentListIsLoadingUntilTheSnapshotArrives(t *testing.T) {
115		a := argRouter(t)
116		a.enterCommandMode() // the load Cmd is not applied
117		typeCommand(t, a, "ctx ")
118	
119		if rows := listRows(t, a); !hasRowWith(rows, "Loading contexts") {
120			t.Errorf("rows %q, want the loading message", rows)
121		}
122	}
123	
124	func TestCtxArgumentWithNoMatchSaysSo(t *testing.T) {
125		a := argRouter(t)
126		ctxOpen(t, a, "ctx wrok")
127	
128		rows := listRows(t, a)
129		if !hasRowWith(rows, `No context starts with "wrok"`) {
130			t.Errorf("rows %q, want the empty message", rows)
131		}
132		if h := highlighted(rows); len(h) != 0 {
133			t.Errorf("highlighted %q on an empty list", h)
134		}
135	}
136	
137	// ── Default highlight ────────────────────────────────────────────────────────
138	
139	func TestCtxArgumentDefaultHighlight(t *testing.T) {
140		cases := []struct {
141			line string
142			want string // substring of the single highlighted row, "" for none
143		}{
144			{"ctx work", "work"}, // exact match
145			{"ctx web", "web"},
146			{"ctx wo", "work"}, // the only match, valid input
147			{"ctx w", ""},      // two matches: nothing chosen (criterion 1)
148			{"ctx ", ""},       // everything matches
149			{"ctx Wo", ""},     // single match but invalid input
150			{"ctx wrok", ""},
151		}
152		for _, c := range cases {
153			t.Run(c.line, func(t *testing.T) {
154				a := argRouter(t)
155				ctxOpen(t, a, c.line)
156				h := highlighted(listRows(t, a))
157				switch {
158				case c.want == "" && len(h) != 0:
159					t.Errorf("highlighted %q, want none", h)
160				case c.want != "" && (len(h) != 1 || !strings.Contains(h[0], c.want)):
161					t.Errorf("highlighted %q, want only %q", h, c.want)
162				}
163			})
164		}
165	}
166	
167	// ── tab ──────────────────────────────────────────────────────────────────────
168	
169	func TestCtxTabHighlightsFirstRowThenCompletes(t *testing.T) {
170		a := argRouter(t)
171		ctxOpen(t, a, "ctx w")
172	
173		press(t, a, "tab")
174		if got := a.commandInput.Value(); got != "ctx w" {
175			t.Errorf("first tab rewrote the line to %q", got)
176		}
177		if h := highlighted(listRows(t, a)); len(h) != 1 || !strings.Contains(h[0], "web") {
178			t.Errorf("first tab highlighted %q, want web", h)
179		}
180	
181		press(t, a, "tab")
182		if got := a.commandInput.Value(); got != "ctx web" {
183			t.Errorf("second tab wrote %q, want %q", got, "ctx web")
184		}
185	}
186	
187	func TestCtxTabWithAHighlightedRowCompletesAtOnce(t *testing.T) {
188		a := argRouter(t)
189		ctxOpen(t, a, "ctx wo")
190	
191		press(t, a, "tab")
192		if got := a.commandInput.Value(); got != "ctx work" {
193			t.Errorf("tab wrote %q, want %q", got, "ctx work")
194		}
195	}
196	
197	func TestCtxTabOnNewLeavesASpaceForTheName(t *testing.T) {
198		a := argRouter(t)
199		ctxOpen(t, a, "ctx n")
200	
201		press(t, a, "tab")
202		if got := a.commandInput.Value(); got != "ctx new " {
203			t.Errorf("tab wrote %q, want %q", got, "ctx new ")
204		}
205	}
206	
207	func TestCtxTabWithNoRowsDoesNothing(t *testing.T) {
208		a := argRouter(t)
209		ctxOpen(t, a, "ctx wrok")
210	
211		press(t, a, "tab")
212		press(t, a, "tab")
213		if got := a.commandInput.Value(); got != "ctx wrok" {
214			t.Errorf("tab rewrote the line to %q", got)
215		}
216	}
217	
218	func TestTabStillCompletesTheCommandWord(t *testing.T) {
219		a := argRouter(t)
220		ctxOpen(t, a, "ctx")
221	
222		press(t, a, "tab")
223		if got := a.commandInput.Value(); got != "ctx " && got != "context " {
224			t.Errorf("tab on the command stage wrote %q", got)
225		}
226	}
227	
228	// ── enter: switching ─────────────────────────────────────────────────────────
229	
230	func requireSwitchTo(t *testing.T, a *App, name string) {
231		t.Helper()
232		if a.commandMode {
233			t.Error("the command line stayed open on a switch")
234		}
235		if a.switchingTo != name {
236			t.Errorf("switchingTo = %q, want %q", a.switchingTo, name)
237		}
238		if want := "Switching to context " + name + "..."; !strings.Contains(a.View(), want) {
239			t.Errorf("the overlay %q is not on screen", want)
240		}
241	}
242	
243	// Criterion 2: ctx wo, tab, enter switches to work.
244	func TestCtxPrefixTabEnterSwitches(t *testing.T) {
245		a := argRouter(t)
246		ctxOpen(t, a, "ctx wo")
247		press(t, a, "tab")
248	
249		press(t, a, "enter")
250		requireSwitchTo(t, a, "work")
251	}
252	
253	func TestCtxExactNameEnterSwitches(t *testing.T) {
254		a := argRouter(t)
